                return true
            }
            switch CMFormatDescriptionGetMediaSubType(description) {
            // 'ap4h' ProRes 4444, 'ap4x' ProRes 4444 XQ, 'rle ' animation.
            case 0x6170_3468, 0x6170_3478, 0x726C_6520:
                return true
            default:
                continue
            }
        }
        return false
    }
