        let height = (props[kCGImagePropertyPixelHeight] as? Int) ?? 0
        guard width > 0, height > 0 else { throw ImportError.unreadable(url) }
        let hasAlpha = (props[kCGImagePropertyHasAlpha] as? Bool) ?? false
